import * as T from './vendor/three.module.js';
// The crown owns its material: ribbon masks must never erase the tree's star.
export function createTreeTopper(parent,{x=0,y=31.2,z=0}={}){
 const root=new T.Group();root.name='crystal-tree-crown';root.position.set(x,y,z);root.userData.keepGroup=true;parent.add(root);
 const outline=Array.from({length:10},(_,i)=>{const a=i*Math.PI/5+Math.PI/2,r=i%2?.57:1.35;return[Math.cos(a)*r,Math.sin(a)*r,0];}),positions=[],edges=[];
 for(let i=0;i<10;i++){const a=outline[i],b=outline[(i+1)%10];const aa=[a[0]*.9,a[1]*.9,.10],bb=[b[0]*.9,b[1]*.9,.10],ab=[a[0]*.9,a[1]*.9,-.10],bbk=[b[0]*.9,b[1]*.9,-.10];positions.push(0,0,.44,...aa,...bb,...a,...b,...bb,...a,...bb,...aa,0,0,-.36,...bbk,...ab,...b,...a,...ab,...b,...ab,...bbk);edges.push(...a,...b,0,0,.445,...aa,0,0,-.365,...ab);}
 const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.Float32BufferAttribute(positions,3));geometry.computeVertexNormals();
 const time={value:0},material=new T.ShaderMaterial({uniforms:{time},toneMapped:false,vertexShader:`varying vec3 vN;varying vec3 vP;varying vec3 vEye;void main(){vN=normalize(normalMatrix*normal);vP=position;vec4 eye=modelViewMatrix*vec4(position,1.);vEye=-eye.xyz;gl_Position=projectionMatrix*eye;}`,fragmentShader:`uniform float time;varying vec3 vN;varying vec3 vP;varying vec3 vEye;void main(){float edge=pow(1.-abs(dot(normalize(vN),normalize(vEye))),2.);float facet=.5+.5*dot(normalize(vN),normalize(vec3(.4,.7,1.)));float shimmer=pow(.5+.5*sin(vP.y*3.-time*.7+vP.x*2.),10.);vec3 color=mix(vec3(.38,.20,.06),vec3(.98,.82,.45),facet);gl_FragColor=vec4(color*(.9+edge*.4+shimmer*.35),1.);}`});
 const star=new T.Mesh(geometry,material);star.name='faceted-five-point-star';root.add(star);
 const rimGeometry=new T.BufferGeometry();rimGeometry.setAttribute('position',new T.Float32BufferAttribute(edges,3));const rimMaterial=new T.LineBasicMaterial({color:'#fff0b7',transparent:true,opacity:.42,toneMapped:false});root.add(new T.LineSegments(rimGeometry,rimMaterial));
 const points=new T.BufferGeometry(),sparkPositions=[0,0,.48,0,0,-.40];for(let i=0;i<5;i++){const a=i*Math.PI*2/5+Math.PI/2;sparkPositions.push(Math.cos(a)*1.38,Math.sin(a)*1.38,0);}points.setAttribute('position',new T.Float32BufferAttribute(sparkPositions,3));
 const glowMaterial=new T.ShaderMaterial({uniforms:{time},transparent:true,depthWrite:false,blending:T.AdditiveBlending,toneMapped:false,vertexShader:`uniform float time;varying float vGlow;varying float vCore;void main(){vCore=step(.8,length(position.xy));vGlow=.5+.5*pow(.5+.5*sin(time*.8+position.y*3.+position.x*2.),5.);vec4 eye=modelViewMatrix*vec4(position,1.);gl_Position=projectionMatrix*eye;gl_PointSize=clamp(mix(4400.,300.,vCore)/max(1.,-eye.z),2.,280.);}`,fragmentShader:`varying float vGlow;varying float vCore;void main(){vec2 p=(gl_PointCoord-.5)*2.;float r=dot(p,p);float glow=exp(-r*4.)*(1.-smoothstep(.6,1.,sqrt(r)));float rays=exp(-abs(p.x)*26.-abs(p.y)*4.)+exp(-abs(p.y)*26.-abs(p.x)*4.);gl_FragColor=vec4(1.,.83,.48,(glow*mix(.14,.45,vCore)+rays*mix(.20,.28,vCore))*vGlow);}`});
 const sparks=new T.Points(points,glowMaterial);sparks.frustumCulled=false;root.add(sparks);
 return{root,update(t,still=false){if(!still&&Number.isFinite(t))time.value=t;},dispose(){for(const g of [geometry,rimGeometry,points])g.dispose();for(const m of [material,rimMaterial,glowMaterial])m.dispose();root.removeFromParent();}};
}
